# Let me check the actual JSON structure more thoroughly
import json

with open('/app/resources/treasury_bulletin_2014_06.json', 'r') as f:
    data = json.load(f)

# The JSON might have tables with all data
print("Keys in JSON:", list(data.keys()))
print()

# Let's look for any fiscal year data in the JSON
if 'document' in data:
    print("Document keys:", list(data['document'].keys()) if isinstance(data['document'], dict) else "not a dict")

# Search all values for 2025
def search_for_2025(obj, path=""):
    found = False
    if isinstance(obj, dict):
        for k, v in obj.items():
            if search_for_2025(v, f"{path}.{k}"):
                found = True
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            if search_for_2025(item, f"{path}[{i}]"):
                found = True
    elif isinstance(obj, str) and "2025" in obj:
        print(f"Found at {path}: {obj[:300]}")
        return True
    elif isinstance(obj, int) and obj == 2025:
        print(f"Found integer 2025 at {path}")
        return True
    return found

# Check for data in document
if 'document' in data:
    search_for_2025(data['document'])
